import{_ as i,c as t,o as a,ag as l}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Terms","description":"","frontmatter":{"title":"Terms"},"headers":[],"relativePath":"general/terms.md","filePath":"general/terms.md","lastUpdated":null}'),n={name:"general/terms.md"};function r(o,e,s,c,g,h){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="terms" tabindex="-1">Terms <a class="header-anchor" href="#terms" aria-label="Permalink to &quot;Terms&quot;">​</a></h1><h3 id="certifications" tabindex="-1">Certifications <a class="header-anchor" href="#certifications" aria-label="Permalink to &quot;Certifications&quot;">​</a></h3><ul><li>Certified Ethical Hacker certification (CEH) <a href="https://www.eccouncil.org/train-certify/certified-ethical-hacker-ceh/" target="_blank" rel="noreferrer">https://www.eccouncil.org/train-certify/certified-ethical-hacker-ceh/</a> - Certified Ethical Hacker (CEH) provides an in-depth understanding of ethical hacking phases, various attack vectors, and preventative countermeasures. &gt; *Insert Context&#39;&#39;</li></ul><h2 id="ai-terminology-cheat-sheet" tabindex="-1">AI Terminology Cheat Sheet <a class="header-anchor" href="#ai-terminology-cheat-sheet" aria-label="Permalink to &quot;AI Terminology Cheat Sheet&quot;">​</a></h2><h3 id="life" tabindex="-1">Life <a class="header-anchor" href="#life" aria-label="Permalink to &quot;Life&quot;">​</a></h3><ul><li><p><strong>Life:</strong> Process that can retain its complexity and replicate.</p></li><li><p><strong>Life 1.0:</strong> Life that evolves its hardware and software (biological stage).</p></li><li><p><strong>Life 2.0:</strong> Life that evolves its hardware but designs much of its software (cultural stage).</p></li><li><p><strong>Life 3.0:</strong> Life that designs its hardware and software (technological stage).</p></li></ul><h3 id="intelligence" tabindex="-1">Intelligence <a class="header-anchor" href="#intelligence" aria-label="Permalink to &quot;Intelligence&quot;">​</a></h3><ul><li><p><strong>Intelligence:</strong> Ability to accomplish complex goals.</p></li><li><p><strong>Artificial Intelligence (AI):</strong> Non-biological intelligence.</p></li><li><p><strong>Narrow intelligence:</strong> Ability to accomplish a narrow set of goals, e.g., play chess or drive a car.</p></li><li><p><strong>General intelligence:</strong> Ability to accomplish virtually any goal, including learning.</p></li><li><p><strong>Universal intelligence:</strong> Ability to acquire general intelligence given access to data and resources.</p></li><li><p><strong>[Human-level] Artificial General Intelligence (AGI):</strong> Ability to accomplish any cognitive task at least as well as humans.</p></li><li><p><strong>Human-level AI:</strong> AGI.</p></li><li><p><strong>Strong AI:</strong> AGI.</p></li><li><p><strong>Superintelligence:</strong> General intelligence far beyond human level.</p></li></ul><h3 id="civilization" tabindex="-1">Civilization <a class="header-anchor" href="#civilization" aria-label="Permalink to &quot;Civilization&quot;">​</a></h3><ul><li><strong>Civilization:</strong> Interacting group of intelligent life forms.</li></ul><h3 id="consciousness" tabindex="-1">Consciousness <a class="header-anchor" href="#consciousness" aria-label="Permalink to &quot;Consciousness&quot;">​</a></h3><ul><li><p><strong>Consciousness:</strong> Subjective experience.</p></li><li><p><strong>Qualia:</strong> Individual instances of subjective experience.</p></li></ul><h3 id="ethics" tabindex="-1">Ethics <a class="header-anchor" href="#ethics" aria-label="Permalink to &quot;Ethics&quot;">​</a></h3><ul><li><strong>Ethics:</strong> Principles that govern how we should behave.</li></ul><h3 id="teleology" tabindex="-1">Teleology <a class="header-anchor" href="#teleology" aria-label="Permalink to &quot;Teleology&quot;">​</a></h3><ul><li><p><strong>Teleology:</strong> Explanation of things in terms of their goals or purposes rather than their causes.</p></li><li><p><strong>Goal-oriented behavior:</strong> Behavior more easily explained via its effect than via its cause.</p></li><li><p><strong>Having a goal:</strong> Exhibiting goal-oriented behavior.</p></li><li><p><strong>Having purpose:</strong> Serving goals of one’s own or of another entity.</p></li><li><p><strong>Friendly AI:</strong> Superintelligence whose goals are aligned with ours.</p></li><li><p><strong>Cyborg:</strong> Human-machine hybrid.</p></li><li><p><strong>Intelligence explosion:</strong> Recursive self-improvement rapidly leading to superintelligence.</p></li><li><p><strong>Singularity:</strong> Intelligence explosion.</p></li></ul><h3 id="universe" tabindex="-1">Universe <a class="header-anchor" href="#universe" aria-label="Permalink to &quot;Universe&quot;">​</a></h3><ul><li><strong>Universe:</strong> The region of space from which light has had time to reach us during the 13.8 billion years since our Big Bang.</li></ul><p>Tegmark, M. (2017). <em>Life 3.0: Being Human in the Age of Artificial Intelligence</em>.</p>',19)])])}const d=i(n,[["render",r]]);export{u as __pageData,d as default};
